"""Kenya National Livestock Database - comprehensive with plain English"""

LIVESTOCK_DATA = [
  {"name":"Dairy Cattle","category":"cattle","purpose":"dairy","water_requirement":"60-80 liters per animal per day","space_required":"4x5m per cow minimum","suitable_aez":["Highland and medium altitude areas with good rainfall"],"description":"Kenya has one of Africa's most developed dairy industries. Smallholder dairy is a major income source in the highlands.","feeding_guide":"Feed 2-3kg of dairy meal per 3 liters of milk produced. Provide quality hay or silage as roughage — at least 30kg fresh napier grass daily. Ensure clean water available at all times. Feed mineral lick blocks. Green fodder like lucerne increases milk production significantly.","housing_requirements":"Zero-grazing unit: concrete floor with drainage channel. Roofed with good ventilation on sides. Feed trough and water trough inside. Size: minimum 4x5m per cow. Separate calf pen. Clean daily and remove manure which is valuable bio-fertilizer.","breeding_info":"Use AI (Artificial Insemination) for high-grade bulls — costs KSh 500-800 per straw from KAGRC. Friesian on local cows gives 50% crossbred. Heifers calve at 24-28 months. Gestation period 9 months. Freshen every 12-13 months for best income.","market_info":"Fresh milk: KSh 35-55 per liter direct to consumer, KSh 25-35 to cooperative. Excess bulls and culled cows: KSh 80,000-200,000 depending on weight. Manure: valuable for own farm use or sell at KSh 500-1,500 per bag.","common_diseases":["East Coast Fever (ECF)","Foot and Mouth Disease (FMD)","Brucellosis","Lumpy Skin Disease","Mastitis","Worms and internal parasites","Ticks and tick-borne diseases"],"vaccination_schedule":[{"vaccine":"East Coast Fever (Muguga Cocktail)","timing":"Once and booster after 1 month, then every 6 months","dose":"2ml subcutaneous injection"},{"vaccine":"Foot and Mouth Disease","timing":"Every 6 months","dose":"2ml injection"},{"vaccine":"Brucellosis (RB51)","timing":"Heifers at 4-8 months of age — once only","dose":"2ml injection"},{"vaccine":"Lumpy Skin Disease","timing":"Annually","dose":"1ml injection"},{"vaccine":"Black Quarter and Anthrax","timing":"Annually before long rains","dose":"5ml injection"}],"breeds":[{"name":"Friesian (Holstein)","origin":"Netherlands","milk_production":"20-35 liters/day crossbred, 40-50L pure in ideal conditions","notes":"Most popular dairy breed in Kenya. Black and white coat. Needs good feeding and housing. Best above 1500m altitude."},{"name":"Ayrshire","origin":"Scotland","milk_production":"15-25 liters/day","notes":"Red and white coat. Excellent milk fat content. More heat tolerant than Friesian. Very popular in Rift Valley."},{"name":"Jersey","origin":"Jersey Island","milk_production":"12-20 liters/day","notes":"Fawn/cream color. Smallest dairy breed. Highest butterfat content — best for butter and yoghurt. Heat tolerant. Good for hotter areas."},{"name":"Guernsey","origin":"Guernsey Island","milk_production":"15-22 liters/day","notes":"Golden-fawn color. High butterfat milk with natural yellow color. Good temperament."},{"name":"Sahiwal","origin":"Pakistan","milk_production":"8-15 liters/day","notes":"Brown zebu-type breed. Very heat and drought tolerant. Tick resistant. Best for lower altitude hot areas."},{"name":"Crossbred (Grade)","origin":"Kenya local x exotic","milk_production":"8-20 liters/day depending on grade","notes":"50-75% exotic blood. Most common on smallholder farms. Good compromise between production and hardiness."}]},

  {"name":"Beef Cattle","category":"cattle","purpose":"meat","water_requirement":"30-50 liters per animal per day","space_required":"Grazing — 2-3 acres per animal, feedlot 3x4m","suitable_aez":["All zones — different breeds suit different areas"],"description":"Beef farming is a major enterprise in ranches, small farms and pastoralist communities across Kenya.","feeding_guide":"Pasture-based: ensure enough quality grass. Supplement with salt licks and mineral blocks. Feedlot finishing: 5-7kg of concentrate daily plus 10kg dry roughage. 90-120 day finishing period for prime beef.","housing_requirements":"Open paddock with shade trees and windbreak. Crush/handling facility essential. Water troughs. Feedlot: covered stalls with concrete floor and good drainage.","breeding_info":"Natural mating: 1 bull per 25 cows. AI available for improved breeds. Calve at 24-30 months. Gestation 9 months. Wean calves at 6-8 months. Slaughter weight 350-500kg at 18-30 months depending on breed.","market_info":"Live animals at livestock markets: KSh 30,000-150,000+ depending on weight and grade. At slaughter: KSh 300-400 per kg live weight. Premium beef to supermarkets: KSh 600-900 per kg cuts.","common_diseases":["Foot and Mouth Disease","East Coast Fever","Contagious Bovine Pleuropneumonia (CBPP)","Bovine Respiratory Disease","Blackleg","Anthrax","Liver Flukes"],"vaccination_schedule":[{"vaccine":"Foot and Mouth Disease","timing":"Every 6 months — very important","dose":"2ml injection"},{"vaccine":"East Coast Fever","timing":"Every 6 months","dose":"2ml injection"},{"vaccine":"CBPP","timing":"Annually","dose":"1ml injection"},{"vaccine":"Blackleg and Anthrax","timing":"Annually before rains","dose":"5ml injection"},{"vaccine":"Rift Valley Fever","timing":"In outbreak areas every 3 years","dose":"1ml injection"}],"breeds":[{"name":"Boran","origin":"Ethiopia/Northern Kenya","weight_kg":"350-550","notes":"Best adapted Kenyan beef breed. Very drought and heat tolerant. Good tick resistance. Ideal for ASAL ranches."},{"name":"Sahiwal x Boran","origin":"Kenya","weight_kg":"300-450","notes":"Common Kenyan crossbred. Good meat yield. Heat tolerant."},{"name":"Simmental","origin":"Switzerland","weight_kg":"450-700","notes":"Large heavily muscled breed. Excellent beef quality. Needs good nutrition. Popular on highland ranches."},{"name":"Angus","origin":"Scotland","weight_kg":"400-600","notes":"Black naturally hornless breed. Excellent marbled beef quality. Premium hotel market."},{"name":"Hereford","origin":"England","weight_kg":"400-600","notes":"Red and white face. Good temperament. Suited to highland ranching."},{"name":"Charolais","origin":"France","weight_kg":"500-750","notes":"White breed. Very fast growing. Excellent feed conversion. Feedlot favorite."}]},

  {"name":"Dairy Goats","category":"goat","purpose":"dairy","water_requirement":"3-6 liters per day","space_required":"2x3m per goat","suitable_aez":["All zones including semi-arid areas"],"description":"Dairy goats are growing rapidly in Kenya. Goat milk is more digestible than cow milk and commands premium prices.","feeding_guide":"Feed 0.5-1kg of goat dairy meal per 2 liters of milk. Provide fresh browse — leucaena, calliandra, desmodium. At least 3-4kg fresh napier grass or hay daily. Clean fresh water always available. Mineral lick block essential.","housing_requirements":"Raised slatted wooden floor goat house — very important for health. Predator-proof with wire mesh sides. Separate kids pen. Milking area should be clean. Size: 2x3m per adult goat.","breeding_info":"Use AI or high grade bucks. Does kid at 12-15 months of age. Twins and triplets common in good breeds. Gestation period 5 months. Kid twice per year possible. Wean kids at 3 months.","market_info":"Fresh goat milk: KSh 80-150 per liter — premium over cow milk. Male kids for meat: KSh 3,000-10,000 depending on age and size. Culled does: KSh 5,000-15,000.","common_diseases":["Pneumonia — most common killer","Enterotoxaemia (Pulpy Kidney)","PPR (Goat Plague)","Foot Rot","Worms — very serious in goats","Lice and mites"],"vaccination_schedule":[{"vaccine":"PPR (Goat Plague)","timing":"Every 3 years","dose":"1ml injection"},{"vaccine":"Enterotoxaemia","timing":"Annually before kidding season","dose":"2ml injection"},{"vaccine":"Foot and Mouth (where required)","timing":"Every 6 months","dose":"2ml injection"},{"vaccine":"Brucellosis","timing":"Female kids once at 3-6 months","dose":"1ml injection"}],"breeds":[{"name":"Toggenburg","origin":"Switzerland","milk_production":"2-4 liters/day","notes":"Brown with white facial stripes. Most popular dairy goat in Kenya. Good milk production."},{"name":"Saanen","origin":"Switzerland","milk_production":"3-6 liters/day","notes":"Large all-white goat. Highest milk producer of all dairy goat breeds. Needs shade and good feeding."},{"name":"Alpine","origin":"French Alps","milk_production":"2-4 liters/day","notes":"Various colors. Hardy and adaptable. Good milk fat content."},{"name":"Anglo-Nubian","origin":"Britain/Middle East","milk_production":"2-4 liters/day","notes":"Long floppy ears. Highest butterfat milk — 5-6%. Good for hotter areas. Dual purpose."},{"name":"Crossbred Dairy Goat","origin":"Kenya","milk_production":"1-3 liters/day","notes":"Toggenburg or Saanen crossed with local goats. More hardy. Good for smallholder farmers."}]},

  {"name":"Meat Goats","category":"goat","purpose":"meat","water_requirement":"2-4 liters per day","space_required":"2x3m per goat or open grazing","suitable_aez":["All zones — very adaptable animal"],"description":"Goat meat (chevon) is the most widely consumed red meat in Kenya. Very high demand especially during festivals and celebrations.","feeding_guide":"Very hardy feeders. Can browse on almost any plant material. Supplement with hay in dry season. Salt lick blocks important. Avoid wet or moldy feeds — goats very sensitive to mycotoxins.","housing_requirements":"Simple predator-proof enclosure at night. Raised floor preferred for health. Separate kidding area.","breeding_info":"Buck serves 30-40 does. Does can kid twice per year. Gestation 5 months. Twins and triplets common. Wean kids at 8 weeks. Slaughter weight 20-35kg at 6-12 months.","market_info":"Live goats at market: KSh 3,000-20,000 depending on weight. Festival premiums (Eid, Christmas) can double prices. Export to Middle East growing demand.","common_diseases":["PPR — Goat Plague most dangerous","Pneumonia","Enterotoxaemia","Foot Rot","Worms — treat every 3 months","Mange and external parasites"],"vaccination_schedule":[{"vaccine":"PPR Vaccine","timing":"Every 3 years","dose":"1ml injection"},{"vaccine":"Enterotoxaemia","timing":"Annually","dose":"2ml injection"},{"vaccine":"Foot and Mouth","timing":"Every 6 months in endemic areas","dose":"2ml injection"}],"breeds":[{"name":"Boer","origin":"South Africa","weight_kg":"60-110","notes":"Most popular meat goat breed worldwide. Fast growing. Good carcass quality. Hornless. Premium price."},{"name":"Galla","origin":"Northern Kenya","weight_kg":"30-50","notes":"White with black head. Indigenous Kenyan breed. Very drought tolerant. Tick resistant."},{"name":"Kiko","origin":"New Zealand","weight_kg":"50-90","notes":"Vigorous meat breed. Very hardy. Parasite resistant. Growing popularity in Kenya."},{"name":"Nyanza Local","origin":"Western Kenya","weight_kg":"20-40","notes":"Local Nyanza region breed. Hardy and adapted. Good disease resistance."},{"name":"Small East African","origin":"East Africa","weight_kg":"20-40","notes":"Most common local goat. Very hardy. Drought tolerant. Low maintenance."}]},

  {"name":"Sheep","category":"sheep","purpose":"meat/wool","water_requirement":"2-4 liters per day","space_required":"1.5x2m per sheep indoors","suitable_aez":["Highland and medium altitude areas"],"description":"Sheep farming provides both meat and wool income. Mutton demand is high especially in urban and Muslim markets.","feeding_guide":"Graze on grass pastures. Supplement with hay in dry season. Do NOT let sheep graze wet grass early morning — causes bloat. Provide mineral lick blocks. Avoid overgrazing — rotate paddocks.","housing_requirements":"Simple roofed shelter for protection from rain and cold. Separate lambing pens. Lambs very vulnerable to cold and dampness in first week.","breeding_info":"Ram serves 25-40 ewes. Gestation period 5 months. Twins common in improved breeds. Wean lambs at 8-10 weeks. Shear wool once or twice per year.","market_info":"Mutton at market: KSh 4,000-20,000 per animal. Wool: KSh 100-300 per kg. Maasai and Muslim market premium for intact male sheep.","common_diseases":["PPR — Sheep and Goat Plague","Enterotoxaemia — Pulpy Kidney","Pneumonia","Nasal Bot Fly","Footrot","Mange","Internal worms — very common"],"vaccination_schedule":[{"vaccine":"PPR Vaccine","timing":"Every 3 years","dose":"1ml injection"},{"vaccine":"Enterotoxaemia","timing":"Annually and before lambing","dose":"2ml injection"},{"vaccine":"Foot Rot vaccine","timing":"Where endemic — every 6 months","dose":"1ml injection"}],"breeds":[{"name":"Dorper","origin":"South Africa","weight_kg":"60-100","notes":"Most popular meat sheep in Kenya. Shedding breed — no shearing needed. Very fast growing. Excellent carcass quality."},{"name":"Merino","origin":"Spain","weight_kg":"50-80","notes":"Best wool breed. Fine quality fiber. Good for highland wool industry."},{"name":"Red Maasai","origin":"Kenya","weight_kg":"35-55","notes":"Indigenous Kenyan breed. Extremely heat and drought tolerant. Resistant to many diseases. Low maintenance."},{"name":"Dorper x Red Maasai","origin":"Kenya","weight_kg":"50-80","notes":"Best crossbred for Kenya. Combines Dorper meat quality with Red Maasai hardiness. Very popular."},{"name":"Corriedale","origin":"New Zealand","weight_kg":"50-80","notes":"Dual purpose — wool and meat. Hardy. Good for highland farms."},{"name":"Blackhead Persian","origin":"South Africa","weight_kg":"40-70","notes":"Drought tolerant. Fat tail breed. Good meat quality. Popular in semi-arid areas."}]},

  {"name":"Broiler Chickens","category":"poultry","purpose":"meat","water_requirement":"500ml-1 liter per bird per day","space_required":"0.1 square meters per bird (10 birds per m2)","suitable_aez":["All zones — indoors production"],"description":"Broiler farming is one of the fastest income turnarounds in farming. A batch of 500 birds gives returns in just 6 weeks.","feeding_guide":"Feed ad libitum (always available) throughout the day. Week 1-2: Starter crumbles 21% protein. Week 3-4: Grower pellets 19% protein. Week 5-6: Finisher pellets 17% protein. Clean fresh water must always be available — reduce water = reduce growth. Add vitamins to water weekly.","housing_requirements":"Deep litter house: closed sided but ventilated. Start with 1m2 per 10 chicks. Expand as birds grow. Target temperature 32°C at day 1, reduce by 2°C per week. Litter: wood shavings or rice hulls 10cm deep. Avoid ammonia buildup — ventilate well.","breeding_info":"Commercial broilers are hybrids — do not breed. Buy day-old chicks from reputable hatchery. Certificate of health required. Batch system — depopulate all birds at same time then clean thoroughly before next batch.","market_info":"Slaughter weight 2-2.5kg at 6 weeks. Live bird: KSh 300-450 per kg. Dressed bird: KSh 400-550 per kg. Urban markets, hotels and restaurants are best markets.","common_diseases":["Newcastle Disease — most serious killer","Gumboro (IBD)","Coccidiosis — bloody droppings","Fowl Typhoid","Infectious Bronchitis","Marek's Disease","Aspergillosis from moldy litter"],"vaccination_schedule":[{"vaccine":"Marek's Disease","timing":"Day 1 at hatchery","dose":"Administered by hatchery"},{"vaccine":"Newcastle Disease (Lasota)","timing":"Day 7 eye drop, Day 28 booster","dose":"Eye drop — 1 drop per bird"},{"vaccine":"Gumboro (IBD)","timing":"Day 14 in drinking water","dose":"In drinking water"},{"vaccine":"Newcastle Disease killed","timing":"Day 21 injection","dose":"0.5ml injection"}],"breeds":[{"name":"Ross 308","origin":"UK (Aviagen)","weight_kg":"2.5 at 6 weeks","notes":"Most popular broiler in Kenya. Very fast growth. Excellent feed conversion. 1kg feed makes 0.5kg meat."},{"name":"Cobb 500","origin":"USA","weight_kg":"2.5 at 6 weeks","notes":"Second most popular. Similar performance to Ross. Good breast meat yield."},{"name":"Hubbard","origin":"France","weight_kg":"2.3 at 6 weeks","notes":"Slightly slower but more robust. Less leg problems. Good for rural areas."},{"name":"Arbor Acres","origin":"USA","weight_kg":"2.4 at 6 weeks","notes":"Good uniformity. Disease tolerance. Popular with medium-scale farmers."},{"name":"Rainbow Rooster","origin":"France","weight_kg":"2.0 at 8 weeks","notes":"Slower colored broiler. Better flavor. Preferred in rural markets and hotels wanting free-range taste."}]},

  {"name":"Layer Chickens","category":"poultry","purpose":"eggs","water_requirement":"300-500ml per bird per day","space_required":"4 birds per m2 in cages, 3 per m2 floor housing","suitable_aez":["All zones — indoors production"],"description":"Layer farming provides steady daily income from egg sales. A flock of 500 layers gives about 450 eggs per day.","feeding_guide":"Feed chick mash in first 8 weeks: 21% protein. Grower mash 8-18 weeks: 17% protein. Layer mash from 18 weeks: 16% protein with high calcium for strong shells. Never run out of feed or water — production drops immediately. Add oyster shell for calcium.","housing_requirements":"Battery cage system: 450 cm2 per bird minimum. Deep litter: 3 birds per m2. Good ventilation very important — reduces respiratory disease. Artificial lighting to maintain 16 hours light daily — boosts egg production significantly.","breeding_info":"Commercial layers do not breed — buy point-of-lay (POL) pullets at 18 weeks. Peak production at 26-30 weeks. A good layer produces 300-320 eggs per year. Replace flock at 72 weeks (18 months) when production drops.","market_info":"Eggs: KSh 10-15 per egg, KSh 280-400 per tray of 30. Spent hens at 18 months: KSh 200-400 per bird for soup chicken market. Manure: KSh 500-1500 per bag — high value especially for horticulture.","common_diseases":["Newcastle Disease — most serious","Gumboro (IBD)","Fowl Typhoid","Egg Drop Syndrome","Avian Influenza (Bird Flu)","Infectious Bronchitis","Coccidiosis","Mycoplasma"],"vaccination_schedule":[{"vaccine":"Marek's Disease","timing":"Day 1 at hatchery","dose":"Hatchery administered"},{"vaccine":"Newcastle (Lasota)","timing":"Day 7, Day 28, then monthly","dose":"Eye drop or water"},{"vaccine":"Gumboro (IBD)","timing":"Day 14, Day 28","dose":"In drinking water"},{"vaccine":"Fowl Typhoid","timing":"Week 6 and 14","dose":"Injection"},{"vaccine":"Infectious Bronchitis","timing":"Week 4 and 14","dose":"Eye drop or spray"},{"vaccine":"Newcastle killed vaccine","timing":"Before laying at 16 weeks","dose":"0.5ml injection"}],"breeds":[{"name":"ISA Brown","origin":"France","eggs_year":"310-320 eggs","notes":"Most popular layer in Kenya. Brown eggs. Excellent feed conversion. Gentle temperament."},{"name":"Lohmann Brown","origin":"Germany","eggs_year":"300-315 eggs","notes":"Brown eggs. Strong shells. Very consistent production. Popular with commercial farmers."},{"name":"Hy-Line Brown","origin":"USA","eggs_year":"310-325 eggs","notes":"Top performance layer. High uniformity. Good livability."},{"name":"Novogen Brown","origin":"France","eggs_year":"305-320 eggs","notes":"Good performance. Heat tolerant. Popular in hot lowland areas."},{"name":"Black Australorp","origin":"Australia","eggs_year":"250-280 eggs","notes":"Good layer. Hardy. Better adapted to free-range conditions than hybrids."}]},

  {"name":"Kienyeji Chickens","category":"poultry","purpose":"dual","water_requirement":"200-300ml per bird per day","space_required":"3 birds per m2 or free range","suitable_aez":["All zones — highly adaptable"],"description":"Indigenous Kenyan chickens. Very popular for their flavorful meat and eggs. Improved Kienyeji breeds give much better performance than pure local birds.","feeding_guide":"Improved Kienyeji feeds well on commercial feeds plus free range foraging. Feed layers mash. Allow to range and find own insects and greens. Supplement with grains. Less intensive than exotic breeds.","housing_requirements":"Simple predator-proof house at night essential. Good ventilation. Can be free-range during day. Deep litter or simple mud/wood house.","breeding_info":"Natural mating. Hen goes broody and hatches own eggs. Incubation 21 days. Allow one hen to hatch then remove other hens. Production is lower but more sustainable without high inputs.","market_info":"Kienyeji eggs: KSh 15-20 per egg — premium over exotic. Kienyeji meat: KSh 600-900 per kg — much higher than broiler. Live bird: KSh 600-1,500 per bird depending on size.","common_diseases":["Newcastle Disease — most important to vaccinate","Gumboro IBD","Fowl Pox","Coccidiosis","External parasites — lice and mites","Worms"],"vaccination_schedule":[{"vaccine":"Newcastle Disease (I-2 thermostable)","timing":"Monthly — in drinking water","dose":"1 dose in drinking water"},{"vaccine":"Fowl Pox","timing":"Every 6 months — wing web stab","dose":"Wing web stab method"}],"breeds":[{"name":"KARI Improved Kienyeji","origin":"Kenya (KALRO)","eggs_year":"150-220 eggs","notes":"Government improved breed. Grows twice as fast as local. Good disease resistance. Very popular with smallholders."},{"name":"Kuroiler","origin":"India","eggs_year":"150-200 eggs","notes":"Colorful breed that forages well. Fast growing. Good for free-range systems."},{"name":"Kenbro","origin":"Kenya","eggs_year":"180-220 eggs","notes":"Kenyan improved breed. Good dual purpose — eggs and meat. Hardy and adaptable."},{"name":"Rainbow Rooster","origin":"France","eggs_year":"150-180 eggs","notes":"Colored slower-growing bird. Excellent flavor preferred in rural and hotel markets."},{"name":"Pure Local/Traditional","origin":"Kenya","eggs_year":"60-100 eggs","notes":"Traditional chicken. Lowest production but highest disease resistance. Very good at foraging."}]},

  {"name":"Turkeys","category":"poultry","purpose":"meat","water_requirement":"500ml-1 liter per turkey per day","space_required":"0.5 square meters per turkey","suitable_aez":["All zones — tolerates a wide range"],"description":"Turkey farming is growing in Kenya especially for Christmas and Thanksgiving market. Very good income in December.","feeding_guide":"Turkeys need high protein diet especially as poults. Starter 28% protein for first 8 weeks. Grower 22% until 16 weeks. Finisher 18% to slaughter. Much larger appetite than chickens. Needs grit for digestion.","housing_requirements":"More space than chickens. Good ventilation. Turkeys very sensitive to dampness. Roosts at 1m height. Outdoor ranging with shade is ideal.","breeding_info":"Natural or AI mating. Tom serves 8-12 hens. Incubation 28 days. Commercial turkeys too heavy for natural mating — need AI. Slaughter at 16-24 weeks at 8-15kg.","market_info":"Christmas turkeys fetch premium prices. Live turkey: KSh 8,000-25,000 depending on size. Dressed at KSh 600-1,000 per kg. Best markets: supermarkets, hotels, expats and churches.","common_diseases":["Blackhead Disease (Histomonosis)","Newcastle Disease","Fowl Cholera","Coccidiosis","Mycoplasma","Do NOT keep with chickens — they share diseases"],"vaccination_schedule":[{"vaccine":"Newcastle Disease","timing":"Monthly in water","dose":"Water administration"},{"vaccine":"Fowl Cholera","timing":"Every 6 months","dose":"Injection"},{"vaccine":"Fowl Pox","timing":"Annually","dose":"Wing web stab"}],"breeds":[{"name":"Broad Breasted White","origin":"USA","weight_kg":"12-18 male, 8-11 female","notes":"Most popular commercial turkey worldwide. Very large breast meat. Cannot mate naturally."},{"name":"Broad Breasted Bronze","origin":"USA","weight_kg":"11-16 male, 7-10 female","notes":"Brown-bronze colored. Good meat yield. Traditional Christmas bird."},{"name":"Beltsville Small White","origin":"USA","weight_kg":"6-8 male, 4-5 female","notes":"Smaller turkey. Can mate naturally. Good for smallholder farmers."}]},

  {"name":"Rabbits","category":"rabbit","purpose":"meat","water_requirement":"200-400ml per rabbit per day","space_required":"0.5 square meters per adult rabbit","suitable_aez":["All zones — very adaptable"],"description":"Rabbit farming gives very fast returns and is easy to start with low capital. Very high protein white meat. Growing urban market demand.","feeding_guide":"Feed fresh green material: napier grass, sweet potato vines, green maize stover, banana leaves, desmodium, lucerne — minimum 200g per rabbit daily. Supplement with rabbit pellets 50-100g per day. Always have fresh water available. Green feeds must not be wet or moldy.","housing_requirements":"Wooden or wire hutches raised 1m off ground — prevents disease. Size 0.5x1m per adult rabbit. Separate doe and kindling boxes for mothers. Wire mesh floor allows droppings to fall below. Cover from rain and direct sun. Good ventilation essential.","breeding_info":"Does breed at 5-6 months. Buck serves doe in buck's hutch only. Gestation period 31 days. Average 6-12 kits per litter. Wean kits at 8 weeks. Doe can breed again 2 weeks after weaning. One doe can produce 30-50 kits per year.","market_info":"Rabbit meat: KSh 400-800 per kg dressed — premium white meat. Live rabbit: KSh 500-2,000 depending on size and breed. Hotels, restaurants and health-conscious urban consumers are best market. Rabbit skins: KSh 50-200 each.","common_diseases":["Rabbit Haemorrhagic Disease (RHD) — sudden death, must vaccinate","Coccidiosis — bloody droppings","Snuffles (Pasteurellosis) — sneezing and nasal discharge","Mange and ear mites","Mastitis in does","Bloat from wrong feeds"],"vaccination_schedule":[{"vaccine":"Rabbit Haemorrhagic Disease (RHD)","timing":"Every 6 months — very important","dose":"0.5ml injection"},{"vaccine":"Myxomatosis (where present)","timing":"Annually","dose":"0.5ml injection"}],"breeds":[{"name":"California White","origin":"USA","weight_kg":"4-5","notes":"White rabbit with black nose, ears and feet. Most popular meat breed in Kenya. Excellent feed conversion."},{"name":"New Zealand White","origin":"USA","weight_kg":"4-5","notes":"All white. Excellent meat yield. Very popular commercial breed."},{"name":"Flemish Giant","origin":"Belgium","weight_kg":"6-10","notes":"Largest rabbit breed. Very high meat yield. Slower growing but bigger carcass."},{"name":"Chinchilla","origin":"France","weight_kg":"3-4","notes":"Grey colored. Good meat and fur. Attractive for dual income."},{"name":"Rex","origin":"France","weight_kg":"3-4","notes":"Velvety fur. Good meat. Fur has additional market value."},{"name":"Dutch","origin":"Netherlands","weight_kg":"2-3","notes":"Bicolor markings. Popular as pet and meat. Smaller carcass."},{"name":"Kenya Mixed Breed","origin":"Kenya","weight_kg":"2-4","notes":"Most common on Kenyan farms. Lower performance but very hardy."}]},

  {"name":"Pigs","category":"pig","purpose":"meat","water_requirement":"6-15 liters per pig per day","space_required":"2x3m per pig (indoor)","suitable_aez":["All zones with good water supply"],"description":"Pig farming gives very fast and profitable returns. Pigs grow very quickly and convert feed efficiently. Growing market for pork in Kenya.","feeding_guide":"Pigs eat almost anything but AVOID garbage, raw cassava or meat products. Feed: Sow and weaners mash 18% protein. Grower and finisher 16% protein. 2-3kg feed per day per 50kg pig. Fresh water unlimited. Kitchen waste supplement: cooked vegetable peels are fine.","housing_requirements":"Concrete floor with smooth walls — easy to clean. Good drainage essential. Shade and ventilation critical — pigs cannot sweat and overheat easily. Wallowing area or sprinkler for cooling in hot weather. Size: 2x3m per adult pig.","breeding_info":"Boar serves 10-20 sows. Sow comes on heat every 21 days. Gestation 3 months, 3 weeks, 3 days (114 days). Average 8-12 piglets per litter. Wean piglets at 4-6 weeks. Two litters per year per sow is good target.","market_info":"Live pig at market: KSh 10,000-35,000+ depending on weight. Pork: KSh 400-700 per kg. Best markets: urban butcheries, pork joints, hotels. Demand is year-round and growing.","common_diseases":["African Swine Fever (ASF) — no cure, very serious. Report immediately","Foot and Mouth Disease","Swine Erysipelas","Parvovirus","Worms — deworm every 3 months","Mange — very common skin disease","Pneumonia"],"vaccination_schedule":[{"vaccine":"Foot and Mouth Disease","timing":"Every 6 months","dose":"2ml injection"},{"vaccine":"Swine Erysipelas","timing":"Every 6 months","dose":"2ml injection"},{"vaccine":"Parvovirus (for breeding animals)","timing":"Annually","dose":"2ml injection"},{"vaccine":"Tetanus (for piglets)","timing":"At castration time","dose":"0.5ml injection"}],"breeds":[{"name":"Large White (Yorkshire)","origin":"England","weight_kg":"250-380","notes":"Most popular pig breed in Kenya. White. Very high fertility. Excellent mother. Good meat quality."},{"name":"Landrace","origin":"Denmark","weight_kg":"250-370","notes":"Long white pig. Excellent lean meat and bacon quality. Very prolific."},{"name":"Duroc","origin":"USA","weight_kg":"250-340","notes":"Red-brown colored. Excellent meat flavor and marbling. Good growth rate."},{"name":"Hampshire","origin":"USA","weight_kg":"200-320","notes":"Black with white belt. Good lean meat. Popular in highland areas."},{"name":"Kenya Local Pig","origin":"Kenya","weight_kg":"60-150","notes":"Small local pig. Hardy and disease resistant. Low feed inputs. Slow growing."}]},

  {"name":"Fish Farming","category":"fish","purpose":"meat","water_requirement":"Requires clean water pond or tank","space_required":"1 fish per 1-5 square meters depending on system","suitable_aez":["All zones with clean water access"],"description":"Fish farming is one of Kenya's fastest growing livestock enterprises. Tilapia and catfish are most popular. Good income in 6-12 months.","feeding_guide":"Tilapia: 35% protein fingerling feed, 25% grower. Feed 3-5% of fish body weight twice daily. Do not overfeed — pollutes water. Catfish: 30-40% protein. Can eat household food waste as supplement. Use certified floating pellets.","housing_requirements":"Earthen ponds: minimum 300 square meters, depth 1.2-1.5m. Line with clay. Inlet and outlet pipes. Or plastic tanks 5,000-10,000 liters. Cage culture in dams and lakes. Recirculating Aquaculture Systems (RAS) for intensive urban farming.","breeding_info":"Tilapia: Sex reverse all-male fingerlings from hatchery — they grow 40% faster than females. Stock at 2-3 fish per m2 for earthen ponds. Harvest at 300-500g in 6-8 months. Catfish stock at 5 per m2, harvest at 1kg in 8-12 months.","market_info":"Tilapia: KSh 300-450 per kg farm gate. Catfish: KSh 350-500 per kg. Urban supermarkets and hotels: KSh 500-800 per kg dressed. Wholesale to fish markets: consistent daily demand.","common_diseases":["Bacterial diseases — columnaris and motile aeromonas","Parasites — ich and flukes","Fungal infections","Water quality problems — low oxygen kills overnight","Predators — otters, kingfishers, herons"],"vaccination_schedule":[{"vaccine":"No vaccines available for fish","timing":"Prevention through water quality management","dose":"Good water quality, probiotics and regular monitoring"}],"breeds":[{"name":"Nile Tilapia (Oreochromis niloticus)","origin":"Africa","weight_kg":"0.3-1","notes":"Most farmed fish in Kenya. Fast growing. Easy feeding. Very good market. Most common in Lake Victoria basin."},{"name":"All-Male Tilapia","origin":"Hatchery","weight_kg":"0.5-1","notes":"Sex-reversed males only. Grow 40% faster than mixed sex. Best for commercial production."},{"name":"African Catfish (Clarias gariepinus)","origin":"Africa","weight_kg":"0.8-3","notes":"Very hardy. Tolerates low oxygen. Can breathe air. High market demand and price. Faster growth."},{"name":"Rainbow Trout (Oncorhynchus mykiss)","origin":"North America","weight_kg":"0.3-0.8","notes":"Cold water fish. Only for highland cold streams and high altitude. Premium price in hotels."},{"name":"Common Carp (Cyprinus carpio)","origin":"Asia","weight_kg":"0.5-2","notes":"Hardy. Easy to grow. Market mostly in areas with Asian communities."}]},

  {"name":"Honey Bees","category":"bees","purpose":"honey/pollination","water_requirement":"Bees find own water — provide source within 500m","space_required":"5 hives per acre maximum","suitable_aez":["All zones with flowering plants"],"description":"Beekeeping provides income from honey, wax, propolis and pollination services. Very low startup cost. Growing demand for natural honey.","feeding_guide":"Bees feed themselves from flowers. During drought or dry season supplement with sugar syrup (1:1 sugar:water). Ensure water source within 500m. Plant bee forage: sunflowers, lucerne, fruit trees, flowering herbs and trees around apiary.","housing_requirements":"Kenya Top Bar Hive (KTBH) — most popular for smallholders. Langstroth hive for commercial production. Log hives still used traditionally. Site hives under trees for shade. Elevate 50cm above ground. Face entrance away from prevailing wind. 50m from houses.","breeding_info":"Queen bee lays 1,500-2,000 eggs per day. Worker bees live 6 weeks. Queen lives 2-5 years. Swarm season: main colony divides — catch swarms to expand. Replace queen every 2 years for best production. Do not open hive in rain or cold morning.","market_info":"Raw honey: KSh 500-1,500 per kg depending on quality and purity. Beeswax: KSh 500-800 per kg. Propolis: KSh 2,000-5,000 per kg. Pollination services for fruit and horticulture farmers growing market. Export market developing.","common_diseases":["American Foulbrood — notifiable disease","European Foulbrood","Varroa Mite — major global problem","Small Hive Beetle","Wax Moth — destroys empty combs","Pesticide poisoning from neighboring farms"],"vaccination_schedule":[{"vaccine":"No vaccines for bees","timing":"Prevention: regular inspection every 2 weeks","dose":"Good apiary management and hygiene practices"}],"breeds":[{"name":"African Honey Bee (Apis mellifera scutellata)","origin":"East Africa","honey_kg_yr":"20-40","notes":"Native Kenyan bee. Very productive. Also defensive — wear full suit. Best adapted to local conditions."},{"name":"Carniolan Bee","origin":"Slovenia/Austria","honey_kg_yr":"30-60","notes":"More gentle imported breed. Higher honey production. Less adapted to Kenya climate."},{"name":"Buckfast Bee","origin":"England","honey_kg_yr":"30-50","notes":"Hybrid breed. Good tempered. Disease resistant. High production."}]},

  {"name":"Camels","category":"camel","purpose":"dairy/meat/transport","water_requirement":"Can go 7-10 days without water — most drought resistant livestock","space_required":"Open grazing — need 5-10 acres per camel in dry areas","suitable_aez":["Very dry arid and semi-arid areas only — ASAL regions"],"description":"Camels are the primary livestock in Kenya's arid north. Camel milk is highly nutritious and in high demand. Camels thrive where no other livestock can survive.","feeding_guide":"Camels browse on thorny acacia, shrubs and bushes that other animals avoid. They survive on salt licks and very little supplementary feed. In severe drought they mobilize fat from their hump. Do not give them wet or moldy feeds.","housing_requirements":"Thorn enclosure (boma) for protection from predators. Shade trees. No housing needed — they are hardy open-air animals adapted to harsh environments.","breeding_info":"Female camel (she-camel) gives birth every 2-3 years. Single calf born after 13-month gestation. Calf nurses for 1-1.5 years. Cows give milk for up to 18 months per lactation. Male camels not needed until 6-7 years old.","market_info":"Camel milk: KSh 100-300 per liter — much higher than cow milk. Premium market in Nairobi, Mombasa and export to Somalia and Gulf. Live camel at livestock market: KSh 80,000-300,000 depending on size. Camel meat gaining urban market.","common_diseases":["Camel Pox — common","Mange — skin disease","Contagious Ecthyma","Trypanosomiasis (Nagana from tsetse fly)","Brucellosis","Internal worms"],"vaccination_schedule":[{"vaccine":"Camel Pox Vaccine","timing":"Annually","dose":"Subcutaneous injection"},{"vaccine":"CBPP Vaccine","timing":"Annually","dose":"Subcutaneous injection"},{"vaccine":"Anthrax","timing":"Annually in endemic areas","dose":"Subcutaneous injection"}],"breeds":[{"name":"Dromedary (One-Hump) Somali","origin":"Somalia/Northern Kenya","milk_production":"3-10 liters/day","notes":"Most common in Kenya. Excellent milk production. Highly drought tolerant."},{"name":"Rendille Camel","origin":"Rendille community Kenya","milk_production":"2-6 liters/day","notes":"Adapted to Marsabit and Isiolo areas. Hardy and disease resistant."},{"name":"Gabbra Camel","origin":"Marsabit/Chalbi Kenya","milk_production":"3-8 liters/day","notes":"Gabbra pastoralist camel. Well adapted to very harsh Chalbi desert conditions."}]},

  {"name":"Donkeys","category":"donkey","purpose":"draft/transport","water_requirement":"10-20 liters per day","space_required":"Open grazing with shade","suitable_aez":["All zones especially dry areas"],"description":"Donkeys are essential working animals for millions of Kenyan farmers. They carry water, firewood, farm produce and plough land.","feeding_guide":"Donkeys thrive on poor quality grass and crop residues that horses cannot survive on. Supplement with salt lick. Never feed donkeys lush green grass alone — causes laminitis (painful feet). Hay and dry grass is better.","housing_requirements":"Simple thorn enclosure at night for protection from predators. Shade in daytime. Clean water source. Hoof trimming every 6-8 weeks essential.","breeding_info":"Mare donkey (jenny) pregnant for 12 months. Single foal usual. Foal weaned at 6 months. Donkeys work from age 3-4 years. Working life up to 25-30 years with good care.","market_info":"Working donkey: KSh 5,000-20,000 depending on size and condition. Donkey cart rental income in rural areas. Donkey meat growing market despite controversy. Donkey skin export to China (ejiao) is emerging though controversial.","common_diseases":["African Horse Sickness (AHS)","Equine Influenza","Tetanus — very common in wounds","Worms — deworm every 3 months","Skin diseases — rain rot and rain scald","Hoof problems — thrush and laminitis"],"vaccination_schedule":[{"vaccine":"African Horse Sickness","timing":"Annually before fly season","dose":"Injection"},{"vaccine":"Tetanus","timing":"Annually and at any wound","dose":"Injection"},{"vaccine":"Equine Influenza","timing":"Annually","dose":"Injection"}],"breeds":[{"name":"East African Standard Donkey","origin":"East Africa","weight_kg":"90-150","notes":"Common working donkey across Kenya. Hardy and adaptable. Good working animal for small farms."},{"name":"Somali Donkey","origin":"Somalia/Northern Kenya","weight_kg":"80-120","notes":"Smaller but very tough. Suited to arid areas. Excellent endurance."},{"name":"Poitou Donkey","origin":"France","weight_kg":"200-300","notes":"Very large draft donkey. Imported for breeding improvement programs."}]},

  {"name":"Ducks","category":"poultry","purpose":"dual","water_requirement":"1-2 liters per duck per day — must have water to dip bill","space_required":"0.5 square meters per duck indoor, or open water","suitable_aez":["All zones especially near water"],"description":"Duck farming provides both eggs and meat. Ducks are hardier than chickens and more disease resistant. Good niche market for hotels and restaurants.","feeding_guide":"Ducks need pelleted feed and must have water to wash food down. Feed layers mash or duck pellets. Allow to range and find own insects, worms and greens near water. Very good at pest control — eat snails that spread liver fluke.","housing_requirements":"Simple predator-proof house at night. Must have water access for bathing and feeding. Pond or dam nearby ideal. Wire mesh floor or deep litter.","breeding_info":"Drake serves 4-6 ducks. Duck eggs hatch in 28 days (Muscovy 35 days). Production: 100-200 eggs per year. Duck eggs more nutritious and larger than chicken eggs. Good market at baking industry.","market_info":"Duck eggs: KSh 25-50 per egg. Dressed duck: KSh 800-1,500 per kg. Live duck: KSh 1,500-4,000. Specialty market — restaurants and hotels wanting variety.","common_diseases":["Duck Virus Hepatitis — vaccinate","Duck Plague (Duck Virus Enteritis)","Avian Influenza","Aspergillosis from moldy feed","Botulism from rotting organic matter in water","Worms"],"vaccination_schedule":[{"vaccine":"Duck Virus Hepatitis","timing":"Ducklings at 1 week","dose":"0.5ml injection"},{"vaccine":"Duck Plague","timing":"Annually","dose":"1ml injection"},{"vaccine":"Avian Influenza (in high risk areas)","timing":"Twice yearly","dose":"Injection"}],"breeds":[{"name":"Pekin (White Pekin)","origin":"China","weight_kg":"3-4","notes":"Most popular meat duck. Fast growing. White feathers. Good carcass."},{"name":"Khaki Campbell","origin":"England","eggs_year":"250-300","notes":"Best egg-laying duck breed. Brown color. Very productive."},{"name":"Muscovy","origin":"South America","weight_kg":"4-7 male, 2-3 female","notes":"Largest domesticated duck. Red face warty patches. Very meaty. Popular on Kenyan farms."},{"name":"Indian Runner","origin":"Indonesia","eggs_year":"200-250","notes":"Stands upright like a penguin. Good layer. Lean meat."},{"name":"Local Kenyan Duck","origin":"Kenya","weight_kg":"1.5-2.5","notes":"Traditional farm duck. Very hardy. Good forager. Disease resistant."}]},

  {"name":"Quail (Kware)","category":"poultry","purpose":"eggs/meat","water_requirement":"50ml per quail per day","space_required":"10-15 quail per square meter","suitable_aez":["All zones — indoor farming"],"description":"Quail farming is a rapidly growing enterprise in Kenya. Very small capital to start. Eggs command premium health food price.","feeding_guide":"Feed quail chick starter 24% protein for first 3 weeks. Quail layer mash 22% protein from week 4. Feed 15-20g per quail per day. Very small feed quantities — economical. Add calcium supplement for good eggshells.","housing_requirements":"Wire cages — 10-15 birds per square meter. Quail are floor birds so cage height 30cm is enough. Simple structure works fine. Keep warm — quail sensitive to cold. Good ventilation.","breeding_info":"Quail start laying at just 6-7 weeks of age! Lay 250-300 eggs per year. Eggs hatch in 17 days. Quail grow to slaughter weight (150-200g) in just 5-6 weeks. Very fast turnover.","market_info":"Quail eggs: KSh 15-30 per egg — premium health food market. Quail meat: KSh 800-1,500 per kg dressed. Target health-conscious urban consumers. Eggs sold in hotels and supermarkets.","common_diseases":["Quail Bronchitis","Ulcerative Enteritis","Aspergillosis","Coccidiosis","Very disease resistant compared to chickens"],"vaccination_schedule":[{"vaccine":"Newcastle Disease (if mixing with chickens)","timing":"Monthly","dose":"Water administration"},{"vaccine":"Generally quail need fewer vaccines than chickens","timing":"Good biosecurity and hygiene most important","dose":""}],"breeds":[{"name":"Japanese Quail (Coturnix japonica)","origin":"Japan","eggs_year":"250-300","notes":"Most popular quail in Kenya. Small. Fast laying. High egg production."},{"name":"Italian Quail","origin":"Italy","eggs_year":"280-320","notes":"White variety. High production. Good egg size."},{"name":"Texas White Quail","origin":"USA","weight_kg":"0.25-0.35","notes":"Meat type quail. Larger body size. Dual purpose."}]},

  {"name":"Ostriches","category":"poultry","purpose":"meat/feathers/skin","water_requirement":"10-15 liters per day","space_required":"Open paddock — 1 acre per 4-5 ostriches","suitable_aez":["Dry medium altitude areas"],"description":"Ostrich farming is a niche enterprise in Kenya. Very high value — meat, leather and feathers all have premium markets.","feeding_guide":"Ostriches graze and eat grass, leaves, roots and grit naturally. Supplement with commercial ostrich pellets. Fresh vegetables and fruits as supplements. Never feed salty or spicy foods. Always have grit available for digestion.","housing_requirements":"Large open paddock essential. Wire fencing 2m high. Simple shade structure. Ostriches run very fast when scared — fencing must be sturdy and smooth to prevent injury.","breeding_info":"One cock serves 2-5 hens. Hen lays 20-80 eggs per year in season. Eggs incubate for 42 days. Chicks very vulnerable in first month. Reach slaughter weight (100-120kg) at 14-18 months.","market_info":"Ostrich leather: KSh 15,000-50,000 per hide — most valuable part. Ostrich meat: KSh 1,500-3,000 per kg — very lean red meat. Feathers: KSh 200-500 per bird. Eggs: KSh 500-2,000 for eating or hatching.","common_diseases":["Newcastle Disease","Parasites — worms and mites","Leg problems — very common in chicks","Aspergillosis — respiratory fungus","Ostrich Pox"],"vaccination_schedule":[{"vaccine":"Newcastle Disease","timing":"Every 6 months","dose":"Injection"},{"vaccine":"Anthrax (endemic areas)","timing":"Annually","dose":"Injection"}],"breeds":[{"name":"African Black Ostrich","origin":"Sub-Saharan Africa","weight_kg":"100-140 male, 90-110 female","notes":"Most popular commercial ostrich. Black male, brown female. Best skin quality."},{"name":"Blue Neck Ostrich","origin":"East Africa","weight_kg":"90-120","notes":"Blue-grey neck. More heat tolerant. Common in Kenya."},{"name":"Red Neck Ostrich","origin":"North Africa","weight_kg":"90-120","notes":"Red neck. Larger. Good for meat production."}]},
]

def get_all_livestock():
    return LIVESTOCK_DATA
